<?php
declare(strict_types=1);
session_start();
require dirname(__DIR__).'/config/config.php';
require_sign_in();
$role=$_SESSION['role']??'';$uid=(int)($_SESSION['user_id']??0);
if(!in_array($role,['system_admin','sub_admin','admin'],true)){http_response_code(403);exit('Your role cannot view school profiles.');}
$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);if(!$id){http_response_code(400);exit('Choose a school.');}
$db=db();$sql='SELECT s.*,creator.name created_by_name,(SELECT u.name FROM school_memberships m JOIN users u ON u.id=m.user_id WHERE m.school_id=s.id AND m.scope=\'manager\' AND u.role=\'director\' ORDER BY m.created_at LIMIT 1) director,(SELECT u.phone FROM school_memberships m JOIN users u ON u.id=m.user_id WHERE m.school_id=s.id AND m.scope=\'manager\' AND u.role=\'director\' ORDER BY m.created_at LIMIT 1) director_phone FROM schools s LEFT JOIN users creator ON creator.id=s.created_by WHERE s.id=?';$params=[$id];
if($role==='admin'){$sql.=' AND EXISTS(SELECT 1 FROM school_memberships m WHERE m.school_id=s.id AND m.user_id=?)';$params[]=$uid;}
$q=$db->prepare($sql);$q->execute($params);$school=$q->fetch();if(!$school){http_response_code(404);exit('School not found in your access.');}
$isReviewer=in_array($role,['system_admin','sub_admin'],true);$error='';$permission=false;
if($role==='admin'){$q=$db->prepare('SELECT active FROM school_edit_permissions WHERE school_id=? AND user_id=?');$q->execute([$id,$uid]);$permission=(bool)$q->fetchColumn();}
if($_SERVER['REQUEST_METHOD']==='POST'){
    verify_csrf();$action=(string)($_POST['action']??'');
    try{
        if(in_array($action,['grant_edit_permission','revoke_edit_permission'],true)){
            if(!$isReviewer){http_response_code(403);exit('Only a system administrator or sub-system administrator can manage edit permission.');}
            $target=(int)($_POST['user_id']??0);$q=$db->prepare("SELECT u.id FROM users u JOIN school_memberships m ON m.user_id=u.id WHERE u.id=? AND m.school_id=? AND u.role='admin' AND u.status='active'");$q->execute([$target,$id]);if(!$q->fetchColumn())throw new DomainException('Choose an active admin appointed to this school.');
            if($action==='grant_edit_permission'){$q=$db->prepare('INSERT INTO school_edit_permissions(school_id,user_id,granted_by,active,granted_at,revoked_at) VALUES(?,?,?,1,CURRENT_TIMESTAMP,NULL) ON DUPLICATE KEY UPDATE granted_by=VALUES(granted_by),active=1,granted_at=CURRENT_TIMESTAMP,revoked_at=NULL');$q->execute([$id,$target,$uid]);$auditAction='grant_school_edit';}
            else{$q=$db->prepare('UPDATE school_edit_permissions SET active=0,revoked_at=CURRENT_TIMESTAMP WHERE school_id=? AND user_id=? AND active=1');$q->execute([$id,$target]);$auditAction='revoke_school_edit';}
            $q=$db->prepare('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,details) VALUES(?,?,?,?,?)');$q->execute([$uid,$auditAction,'school',$id,json_encode(['admin_id'=>$target],JSON_THROW_ON_ERROR)]);header('Location: school_edit_review.php?id='.$id.'&permission_updated=1');exit;
        }
        if($action==='request_school_update'){
            if($role!=='admin'){http_response_code(403);exit('Only an appointed admin can submit an edit request.');}
            if($permission)throw new DomainException('You have edit permission. Use the direct edit form instead.');
            $name=trim((string)($_POST['name']??''));$location=trim((string)($_POST['location']??''));$phone=trim((string)($_POST['phone']??''));if($name===''||mb_strlen($name)>180||mb_strlen($location)>180||mb_strlen($phone)>30)throw new DomainException('Enter a school name, a location up to 180 characters, and a phone number up to 30 characters.');
            $q=$db->prepare("SELECT id FROM school_edit_requests WHERE school_id=? AND requested_by=? AND status='pending' LIMIT 1");$q->execute([$id,$uid]);if($q->fetchColumn())throw new DomainException('You already have a pending edit request for this school.');
            $q=$db->prepare('INSERT INTO school_edit_requests(school_id,requested_by,original_name,original_location,original_phone,proposed_name,proposed_location,proposed_phone) VALUES(?,?,?,?,?,?,?,?)');$q->execute([$id,$uid,$school['name'],$school['location'],$school['phone'],$name,$location?:null,$phone?:null]);$requestId=(int)$db->lastInsertId();$q=$db->prepare('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,details) VALUES(?,?,?,?,?)');$q->execute([$uid,'request_school_edit','school_edit_request',$requestId,json_encode(['school_id'=>$id,'proposed_name'=>$name,'proposed_location'=>$location?:null,'proposed_phone'=>$phone?:null],JSON_THROW_ON_ERROR)]);header('Location: school_edit_review.php?id='.$id.'&request_sent=1');exit;
        }
        if($action==='update_school'){
            if(!$isReviewer&&!($role==='admin'&&$permission)){http_response_code(403);exit('A system administrator or sub-system administrator must grant edit permission first.');}
            $name=trim((string)($_POST['name']??''));$location=trim((string)($_POST['location']??''));$phone=trim((string)($_POST['phone']??''));if($name===''||mb_strlen($name)>180||mb_strlen($location)>180||mb_strlen($phone)>30)throw new DomainException('Enter a school name, a location up to 180 characters, and a phone number up to 30 characters.');
            $db->beginTransaction();$q=$db->prepare('UPDATE schools SET name=?,location=?,phone=? WHERE id=?');$q->execute([$name,$location?:null,$phone?:null,$id]);$q=$db->prepare('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,details) VALUES(?,?,?,?,?)');$q->execute([$uid,'update','school',$id,json_encode(['before'=>['name'=>$school['name'],'location'=>$school['location'],'phone'=>$school['phone']],'after'=>['name'=>$name,'location'=>$location?:null,'phone'=>$phone?:null]],JSON_THROW_ON_ERROR)]);$db->commit();header('Location: school_view.php?id='.$id.'&saved=1');exit;
        }
        if(in_array($action,['approve_school_edit','deny_school_edit','revert_school_edit'],true)){
            if(!$isReviewer){http_response_code(403);exit('Only a system administrator or sub-system administrator can review school edits.');}
            $requestId=(int)($_POST['request_id']??0);$db->beginTransaction();$q=$db->prepare('SELECT * FROM school_edit_requests WHERE id=? AND school_id=? FOR UPDATE');$q->execute([$requestId,$id]);$request=$q->fetch();if(!$request)throw new DomainException('Edit request not found.');
            if($action==='deny_school_edit'){$q=$db->prepare("UPDATE school_edit_requests SET status='denied',reviewed_by=?,reviewed_at=CURRENT_TIMESTAMP WHERE id=? AND status='pending'");$q->execute([$uid,$requestId]);if(!$q->rowCount())throw new DomainException('This request has already been reviewed.');$auditAction='deny_school_edit';}
            elseif($action==='approve_school_edit'){
                if($request['status']!=='pending')throw new DomainException('This request has already been reviewed.');
                if($school['name']!==$request['original_name']||$school['location']!==$request['original_location']||$school['phone']!==$request['original_phone'])throw new DomainException('The school details changed after this request was submitted. Review the current details before approving.');
                $q=$db->prepare('UPDATE schools SET name=?,location=?,phone=? WHERE id=?');$q->execute([$request['proposed_name'],$request['proposed_location'],$request['proposed_phone'],$id]);$q=$db->prepare("UPDATE school_edit_requests SET status='approved',reviewed_by=?,reviewed_at=CURRENT_TIMESTAMP WHERE id=? AND status='pending'");$q->execute([$uid,$requestId]);if(!$q->rowCount())throw new DomainException('This request has already been reviewed.');$auditAction='approve_school_edit';
            }else{
                if($request['status']!=='approved')throw new DomainException('Only an approved edit can be reverted.');
                if($school['name']!==$request['proposed_name']||$school['location']!==$request['proposed_location']||$school['phone']!==$request['proposed_phone'])throw new DomainException('The school details changed again after approval. Review the current details before reverting.');
                $q=$db->prepare('UPDATE schools SET name=?,location=?,phone=? WHERE id=?');$q->execute([$request['original_name'],$request['original_location'],$request['original_phone'],$id]);$q=$db->prepare("UPDATE school_edit_requests SET status='reverted',reviewed_by=?,reviewed_at=CURRENT_TIMESTAMP WHERE id=? AND status='approved'");$q->execute([$uid,$requestId]);if(!$q->rowCount())throw new DomainException('This edit has already been reverted.');$auditAction='revert_school_edit';
            }
            $q=$db->prepare('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,details) VALUES(?,?,?,?,?)');$q->execute([$uid,$auditAction,'school_edit_request',$requestId,json_encode(['school_id'=>$id],JSON_THROW_ON_ERROR)]);$db->commit();header('Location: school_edit_review.php?id='.$id.'&review_updated=1');exit;
        }
    }catch(DomainException $ex){if($db->inTransaction())$db->rollBack();$error=$ex->getMessage();}
    catch(Throwable $ex){if($db->inTransaction())$db->rollBack();$error='The school edit action could not be completed. Apply the latest database migration and try again.';}
}
$saved=isset($_GET['saved']);
$q=$db->prepare('SELECT c.id,c.name,(SELECT COUNT(*) FROM pupils p WHERE p.school_id=c.school_id AND p.class_level=c.name AND p.status=\'active\') pupil_count,(SELECT COUNT(*) FROM school_streams st WHERE st.class_id=c.id) stream_count,(SELECT COUNT(*) FROM school_class_subjects sj WHERE sj.class_id=c.id) subject_count FROM school_classes c WHERE c.school_id=? ORDER BY c.name');$q->execute([$id]);$classes=$q->fetchAll();
$q=$db->prepare('SELECT COUNT(*) FROM pupils WHERE school_id=? AND status=\'active\'');$q->execute([$id]);$pupils=(int)$q->fetchColumn();
$q=$db->prepare('SELECT COUNT(DISTINCT a.user_id) FROM teacher_assignments a WHERE a.school_id=? AND a.active=1');$q->execute([$id]);$teachers=(int)$q->fetchColumn();
$q=$db->prepare('SELECT COUNT(*) FROM school_exams WHERE school_id=?');$q->execute([$id]);$exams=(int)$q->fetchColumn();
$appointedAdmins=[];$editRequests=[];$q=$db->prepare("SELECT u.id,u.name,u.email,p.active edit_allowed FROM school_memberships m JOIN users u ON u.id=m.user_id LEFT JOIN school_edit_permissions p ON p.school_id=m.school_id AND p.user_id=u.id WHERE m.school_id=? AND u.role='admin' AND u.status='active' ORDER BY u.name");$q->execute([$id]);$appointedAdmins=$q->fetchAll();
if($isReviewer){$q=$db->prepare('SELECT r.*,u.name requested_by_name,reviewer.name reviewer_name FROM school_edit_requests r JOIN users u ON u.id=r.requested_by LEFT JOIN users reviewer ON reviewer.id=r.reviewed_by WHERE r.school_id=? ORDER BY (r.status=\'pending\') DESC,r.created_at DESC LIMIT 50');$q->execute([$id]);$editRequests=$q->fetchAll();}
else{$q=$db->prepare('SELECT r.*,u.name requested_by_name,reviewer.name reviewer_name FROM school_edit_requests r JOIN users u ON u.id=r.requested_by LEFT JOIN users reviewer ON reviewer.id=r.reviewed_by WHERE r.school_id=? AND r.requested_by=? ORDER BY r.created_at DESC LIMIT 20');$q->execute([$id,$uid]);$editRequests=$q->fetchAll();}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($school['name'])?> · School profile</title><link rel="stylesheet" href="assets/app.css"></head><body><div class="app-shell"><aside class="sidebar"><a class="brand" href="index.php"><span class="brand-mark">S</span><span>shule<span class="brand-lite">lite</span></span></a><div class="workspace-label">WORKSPACE</div><nav class="side-nav" aria-label="Main navigation"><a class="nav-item" href="index.php">⌂ &nbsp;Overview</a><a class="nav-item active" href="schools.php">▦ &nbsp;Schools</a><a class="nav-item" href="team.php">♧ &nbsp;People</a><?php if(in_array($_SESSION['role']??'', ['system_admin','sub_admin'],true)):?><a class="nav-item" href="requests.php">✉ &nbsp;Requests<?php $requestBadgeCount=pending_school_edit_request_count();if($requestBadgeCount):?><span class="side-nav-count"><?=$requestBadgeCount>99?'99+':$requestBadgeCount?></span><?php endif;?></a><?php endif;?><?php if(in_array($_SESSION['role']??'', ['system_admin','sub_admin','director'],true)):?><a class="nav-item" href="subscriptions.php">◷ &nbsp;Subscriptions</a><?php endif;?></nav><div class="sidebar-bottom"><a class="nav-item" href="logout.php">↪ &nbsp;Sign out</a></div></aside><main class="main-area"><header class="topbar"><div class="crumb">Workspace <span>/</span><a href="schools.php">Schools</a><span>/</span>View</div><?php if(in_array($_SESSION['role']??'', ['system_admin','sub_admin'],true)):$pendingEditCount=pending_school_edit_request_count();?><a class="notification-bell" href="requests.php#requested" aria-label="<?=$pendingEditCount?> pending edit requests" title="<?=$pendingEditCount?> pending edit requests"><span aria-hidden="true">🔔</span><?php if($pendingEditCount):?><span class="notification-badge"><?=$pendingEditCount>99?'99+':$pendingEditCount?></span><?php endif;?></a><?php endif;?><div class="top-actions"><span class="role-chip"><?=e(str_replace('_',' ',$role))?></span><div class="user-name"><?=e($_SESSION['name']??'')?></div></div></header><div class="page-content"><section class="setup-hero"><div><div class="eyebrow">SCHOOL PROFILE</div><h1><?=e($school['name'])?></h1><p class="muted"><?=e($school['location']?:'Location not recorded')?></p></div><div class="academic-row-actions"><button type="button" class="button primary" data-open-school-edit><?=($role==='admin'&&!$permission)?'Request details change':'Edit details'?></button><a class="button" href="school_edit_review.php?id=<?=$id?>"><?=($isReviewer)?'Manage edit access':'Edit requests'?></a><a class="button" href="school_analyze.php?id=<?=$id?>">Analyze</a><a class="button" href="schools.php">Back to schools</a></div></section><?php if($saved):?><div class="notice success" role="status">School details updated.</div><?php endif;?><?php if($error):?><div class="notice error" role="alert"><?=e($error)?></div><?php endif;?><section class="metric-grid"><article class="metric-card"><div class="metric-label">ACTIVE PUPILS</div><div class="metric-value"><?=number_format($pupils)?></div><div class="metric-note">Currently enrolled</div></article><article class="metric-card"><div class="metric-label">CLASSES</div><div class="metric-value"><?=count($classes)?></div><div class="metric-note">Registered class levels</div></article><article class="metric-card"><div class="metric-label">TEACHERS</div><div class="metric-value"><?=number_format($teachers)?></div><div class="metric-note">With active teaching assignments</div></article><article class="metric-card"><div class="metric-label">EXAMS</div><div class="metric-value"><?=$exams?></div><div class="metric-note">Created assessment records</div></article></section><section class="content-section"><div class="section-heading"><div><div class="eyebrow">SCHOOL DETAILS</div><h2>Overview</h2></div></div><div class="table-wrap"><table><tbody><tr><th>Director</th><td><?=e($school['director']?:'—')?><?=($school['director_phone']?' · '.e($school['director_phone']):'')?></td></tr><tr><th>School phone</th><td><?=e($school['phone']?:'—')?></td></tr><tr><th>Status</th><td><?=e(ucfirst($school['status']))?></td></tr><tr><th>Created by</th><td><?=e($school['created_by_name']?:'Deleted account')?></td></tr><tr><th>Created on</th><td><?=e(date('j M Y',strtotime($school['created_at'])))?></td></tr></tbody></table></div></section><section class="content-section"><div class="section-heading"><div><div class="eyebrow">ACADEMIC STRUCTURE</div><h2>Classes</h2></div><span class="count-pill"><?=count($classes)?> classes</span></div><?php if($classes):?><div class="table-wrap"><table><thead><tr><th>Class</th><th>Active pupils</th><th>Streams</th><th>Subjects</th></tr></thead><tbody><?php foreach($classes as $class):?><tr><th><?=e($class['name'])?></th><td><?=number_format((int)$class['pupil_count'])?></td><td><?=number_format((int)$class['stream_count'])?></td><td><?=number_format((int)$class['subject_count'])?></td></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="empty-state"><h3>No classes registered</h3><p>This school has not added its class structure yet.</p></div><?php endif;?></section></div></main></div><dialog class="academic-dialog school-edit-dialog" id="school-edit-dialog" aria-labelledby="school-edit-title"><form method="post" class="note-form"><div class="academic-dialog-head"><div><div class="eyebrow">SCHOOL DETAILS</div><h2 id="school-edit-title"><?=($role==='admin'&&!$permission)?'Request a school detail change':'Edit school details'?></h2><p class="muted"><?=($role==='admin'&&!$permission)?'Your change will be reviewed by a system administrator or sub-system administrator.':'Update the school name and location.'?></p></div><button type="button" class="icon-button" data-close-school-edit aria-label="Close edit school form">×</button></div><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="<?=($role==='admin'&&!$permission)?'request_school_update':'update_school'?>"><label for="edit-school-name">School name</label><input id="edit-school-name" name="name" maxlength="180" value="<?=e($_POST['name']??$school['name'])?>" required><label for="edit-school-location">Location</label><input id="edit-school-location" name="location" maxlength="180" value="<?=e($_POST['location']??$school['location']??'')?>"><label for="edit-school-phone">School phone</label><input id="edit-school-phone" name="phone" type="tel" maxlength="30" autocomplete="tel" value="<?=e($_POST['phone']??$school['phone']??'')?>"><div class="academic-dialog-actions"><button type="button" class="button" data-close-school-edit>Cancel</button><button class="button primary" type="submit"><?=($role==='admin'&&!$permission)?'Submit request':'Save details'?></button></div></form></dialog><script>const schoolEditDialog=document.getElementById("school-edit-dialog");document.querySelector("[data-open-school-edit]")?.addEventListener("click",()=>schoolEditDialog.showModal());document.querySelectorAll("[data-close-school-edit]").forEach(button=>button.addEventListener("click",()=>schoolEditDialog.close()));<?php if($error):?>schoolEditDialog.showModal();<?php endif;?></script></body></html>
